create extension if not exists pgcrypto;
create table if not exists public.categories(id uuid primary key default gen_random_uuid(),slug text not null unique,name text not null,sort_order integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.brands(id uuid primary key default gen_random_uuid(),slug text not null unique,name text not null,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.products(id text primary key,slug text not null unique,name text not null,category_id uuid not null references public.categories(id),brand_id uuid references public.brands(id),price numeric(10,2) not null check(price>=0),compare_at_price numeric(10,2) check(compare_at_price is null or compare_at_price>=price),currency char(3) not null default 'EUR',source_url text,description text not null default '',rating numeric(2,1) not null default 0 check(rating between 0 and 5),reviews integer not null default 0 check(reviews>=0),badge text,details jsonb not null default '[]'::jsonb,status text not null default 'draft' check(status in('draft','published','archived')),stock integer check(stock is null or stock>=0),is_featured boolean not null default false,is_b2b boolean not null default false,sort_order integer not null default 0,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.product_images(id uuid primary key default gen_random_uuid(),product_id text not null references public.products(id) on delete cascade,url text not null,position integer not null default 0,alt text,created_at timestamptz not null default now(),unique(product_id,position));
create index if not exists products_status_sort_idx on public.products(status,sort_order);
create index if not exists products_category_idx on public.products(category_id);
create index if not exists products_brand_idx on public.products(brand_id);
create index if not exists product_images_product_position_idx on public.product_images(product_id,position);
create or replace function public.set_updated_at() returns trigger language plpgsql as $$ begin new.updated_at=now();return new;end $$;
drop trigger if exists categories_set_updated_at on public.categories;create trigger categories_set_updated_at before update on public.categories for each row execute function public.set_updated_at();
drop trigger if exists brands_set_updated_at on public.brands;create trigger brands_set_updated_at before update on public.brands for each row execute function public.set_updated_at();
drop trigger if exists products_set_updated_at on public.products;create trigger products_set_updated_at before update on public.products for each row execute function public.set_updated_at();
alter table public.categories enable row level security;alter table public.brands enable row level security;alter table public.products enable row level security;alter table public.product_images enable row level security;
drop policy if exists "Public read categories" on public.categories;create policy "Public read categories" on public.categories for select using(true);
drop policy if exists "Public read brands" on public.brands;create policy "Public read brands" on public.brands for select using(true);
drop policy if exists "Public read published products" on public.products;create policy "Public read published products" on public.products for select using(status='published');
drop policy if exists "Public read published product images" on public.product_images;create policy "Public read published product images" on public.product_images for select using(exists(select 1 from public.products p where p.id=product_id and p.status='published'));
